import os,socket,array,struct,stat,fcntl
def receive_readonly(connection,expected_uid,limit):
    if type(expected_uid) is not int or expected_uid<0 or type(limit) is not int or not 1<=limit<=65536:raise ValueError('uid and limit')
    pid,uid,gid=struct.unpack('3i',connection.getsockopt(socket.SOL_SOCKET,socket.SO_PEERCRED,struct.calcsize('3i')))
    if uid!=expected_uid:raise PermissionError('unexpected peer')
    descriptors=[]
    try:
        data,ancillary,flags,address=connection.recvmsg(1,socket.CMSG_SPACE(16*array.array('i').itemsize),socket.MSG_CMSG_CLOEXEC)
        for level,kind,raw in ancillary:
            if level==socket.SOL_SOCKET and kind==socket.SCM_RIGHTS:
                values=array.array('i');values.frombytes(raw[:len(raw)//values.itemsize*values.itemsize]);descriptors.extend(values)
        if flags&socket.MSG_CTRUNC or data!=b'F' or len(descriptors)!=1:raise ValueError('exactly one descriptor')
        fd=descriptors[0]
        if not stat.S_ISREG(os.fstat(fd).st_mode) or fcntl.fcntl(fd,fcntl.F_GETFL)&os.O_ACCMODE!=os.O_RDONLY:raise ValueError('readonly regular file required')
        os.set_inheritable(fd,False)
        payload=os.pread(fd,limit+1,0)
        if len(payload)>limit:raise ValueError('size limit')
        return payload
    finally:
        for fd in descriptors:os.close(fd)
